-- Generated by posgmo-factory (tests/prd_companyFeature.json, local export,
-- FACTORY_SQL_MODE=validate: executed and rolled back, review 100/100/100).
-- Per-company feature switch: no row = OFF. First feature
-- SERVICE_COMPLETION_NOTICE (modules/serviceCompletionNotices.py), enabled for
-- companyId 1 (Lavanderia GMO) only. Re-runnable.
-- Run on DEV, then QA, then PROD (check the [appEnv] banner / target DB first).
-- dbo.users has no PK, so updatedByUserId has no FK (factory-sql-apply note).
-- =============================================================================

IF OBJECT_ID('dbo.companyFeatures', 'U') IS NULL
BEGIN
CREATE TABLE [dbo].[companyFeatures] (
    companyFeatureId    INT IDENTITY(1,1) NOT NULL,
    companyId           INT NOT NULL,
    featureKey          NVARCHAR(50) NOT NULL,
    enabled             BIT NOT NULL DEFAULT 0,
    configJson          NVARCHAR(MAX) NULL,
    updatedByUserId     INT NULL,
    created_At          DATETIME NOT NULL DEFAULT GETDATE(),
    updated_at          DATETIME NULL,
    CONSTRAINT PK_companyFeatures PRIMARY KEY CLUSTERED (companyFeatureId ASC),
    CONSTRAINT FK_companyFeatures_companies FOREIGN KEY (companyId) REFERENCES dbo.companies (companyId),
    CONSTRAINT UQ_companyFeatures_companyId_featureKey UNIQUE NONCLUSTERED (companyId, featureKey),
    CONSTRAINT CK_companyFeatures_configJson_IsJson CHECK (configJson IS NULL OR ISJSON(configJson) = 1)
);
END
GO

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'IX_companyFeatures_companyId' AND object_id = OBJECT_ID('dbo.companyFeatures'))
    CREATE NONCLUSTERED INDEX IX_companyFeatures_companyId ON dbo.companyFeatures (companyId);
GO

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'IX_companyFeatures_updatedByUserId' AND object_id = OBJECT_ID('dbo.companyFeatures'))
    CREATE NONCLUSTERED INDEX IX_companyFeatures_updatedByUserId ON dbo.companyFeatures (updatedByUserId);
GO

CREATE OR ALTER PROC [dbo].[sp_companyFeatures] (@pjsonfile VARCHAR(MAX))
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Outputmessage NVARCHAR(MAX) = '{
      "result": [
        { "value": "", "msg": "", "error": "" }
      ]
    }';

    DECLARE @action INT;
    SET @action = (
        SELECT TOP 1 TRY_CONVERT(INT, JSON_VALUE(value, '$.action'))
        FROM OPENJSON(@pjsonfile, '$.companyFeatures')
    );

    DECLARE @payload TABLE (
        companyFeatureId    INT NULL,
        companyId           INT NULL,
        featureKey          NVARCHAR(50) NULL,
        enabled             BIT NULL,
        configJson          NVARCHAR(MAX) NULL,
        updatedByUserId     INT NULL
    );

    INSERT INTO @payload (companyFeatureId, companyId, featureKey, enabled, configJson, updatedByUserId)
    SELECT
        TRY_CONVERT(INT, JSON_VALUE(value, '$.companyFeatureId')),
        TRY_CONVERT(INT, JSON_VALUE(value, '$.companyId')),
        JSON_VALUE(value, '$.featureKey'),
        TRY_CONVERT(BIT, JSON_VALUE(value, '$.enabled')),
        JSON_VALUE(value, '$.configJson'),
        TRY_CONVERT(INT, JSON_VALUE(value, '$.updatedByUserId'))
    FROM OPENJSON(@pjsonfile, '$.companyFeatures');

    BEGIN TRY
        BEGIN TRANSACTION;

        IF @action = 1 -- INSERT (with upsert logic for existing unique key: companyId, featureKey)
        BEGIN
            -- Validate for duplicates within the payload itself
            IF EXISTS (SELECT 1 FROM @payload GROUP BY companyId, featureKey HAVING COUNT(*) > 1)
            BEGIN
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Duplicate featureKey found for the same company in the input payload.');
                COMMIT TRANSACTION;
                GOTO Finish;
            END

            DECLARE @existingCompanyFeatureId INT;
            DECLARE @companyId_val INT;
            DECLARE @featureKey_val NVARCHAR(50);
            DECLARE @enabled_val BIT;
            DECLARE @configJson_val NVARCHAR(MAX);
            DECLARE @updatedByUserId_val INT;

            -- Process each item in the payload for INSERT/UPSERT
            DECLARE payload_cursor CURSOR LOCAL FAST_FORWARD FOR
            SELECT companyId, featureKey, enabled, configJson, updatedByUserId
            FROM @payload;

            OPEN payload_cursor;
            FETCH NEXT FROM payload_cursor INTO @companyId_val, @featureKey_val, @enabled_val, @configJson_val, @updatedByUserId_val;

            WHILE @@FETCH_STATUS = 0
            BEGIN
                SET @existingCompanyFeatureId = NULL;

                -- Check if a row with the same companyId and featureKey already exists
                SELECT @existingCompanyFeatureId = companyFeatureId
                FROM dbo.companyFeatures WITH (UPDLOCK, HOLDLOCK)
                WHERE companyId = @companyId_val AND featureKey = @featureKey_val;

                IF @existingCompanyFeatureId IS NOT NULL -- Row exists, perform an update
                BEGIN
                    UPDATE dbo.companyFeatures
                    SET
                        enabled = ISNULL(@enabled_val, enabled), -- Use existing value if not provided, otherwise update
                        configJson = @configJson_val,
                        updatedByUserId = @updatedByUserId_val,
                        updated_at = GETDATE()
                    WHERE companyFeatureId = @existingCompanyFeatureId;
                END
                ELSE -- Row does not exist, perform an insert
                BEGIN
                    INSERT INTO dbo.companyFeatures (companyId, featureKey, enabled, configJson, updatedByUserId, created_At)
                    VALUES (@companyId_val, @featureKey_val, ISNULL(@enabled_val, 0), @configJson_val, @updatedByUserId_val, GETDATE());
                END

                FETCH NEXT FROM payload_cursor INTO @companyId_val, @featureKey_val, @enabled_val, @configJson_val, @updatedByUserId_val;
            END;

            CLOSE payload_cursor;
            DEALLOCATE payload_cursor;

            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Inserted/Upserted Successfully');
        END
        ELSE IF @action = 2 -- UPDATE
        BEGIN
            -- Validate companyFeatureId is present for a direct update
            IF NOT EXISTS (SELECT 1 FROM @payload WHERE companyFeatureId IS NOT NULL)
            BEGIN
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'companyFeatureId is required for update action.');
                COMMIT TRANSACTION;
                GOTO Finish;
            END

            -- Check for unique constraint violation on (companyId, featureKey) against *other* rows
            IF EXISTS (
                SELECT 1
                FROM @payload p
                INNER JOIN dbo.companyFeatures cf ON p.companyId = cf.companyId AND p.featureKey = cf.featureKey
                WHERE cf.companyFeatureId <> p.companyFeatureId
            )
            BEGIN
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Duplicate companyId and featureKey combination for another feature already exists.');
                COMMIT TRANSACTION;
                GOTO Finish;
            END

            UPDATE cf
            SET
                cf.companyId = p.companyId,
                cf.featureKey = p.featureKey,
                cf.enabled = p.enabled,
                cf.configJson = p.configJson,
                cf.updatedByUserId = p.updatedByUserId,
                cf.updated_at = GETDATE()
            FROM dbo.companyFeatures cf
            INNER JOIN @payload p ON cf.companyFeatureId = p.companyFeatureId;

            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Updated Successfully');
        END
        ELSE IF @action = 3 -- DELETE (Rejected as per PRD hint)
        BEGIN
            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'DELETE action is not allowed for companyFeatures. Use UPDATE to set enabled = 0.');
            COMMIT TRANSACTION;
            GOTO Finish;
        END
        ELSE
        BEGIN
            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Invalid action specified.');
            COMMIT TRANSACTION;
            GOTO Finish;
        END

        COMMIT TRANSACTION;

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
        SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', ERROR_MESSAGE());
    END CATCH;

Finish:
    SELECT
        JSON_VALUE(value,'$.value') AS value,
        JSON_VALUE(value,'$.msg')   AS msg,
        JSON_VALUE(value,'$.error') AS error
    FROM OPENJSON(@Outputmessage,'$.result');
END;
GO

CREATE OR ALTER PROC [dbo].[sp_companyFeatures_all] (@pjsonfile VARCHAR(MAX))
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @companyId INT;
    DECLARE @enabledOnly BIT;

    -- Extract companyId and enabledOnly from the JSON input
    SELECT
        @companyId = TRY_CONVERT(INT, JSON_VALUE(value, '$.companyId')),
        @enabledOnly = TRY_CONVERT(BIT, JSON_VALUE(value, '$.enabledOnly'))
    FROM OPENJSON(@pjsonfile, '$.companyFeatures'); -- Assumes companyFeatures array contains these parameters

    SELECT
        [companyFeatureId],
        ISNULL([companyId], 0) AS companyId,
        ISNULL([featureKey], '') AS featureKey,
        ISNULL([enabled], 0) AS enabled,
        ISNULL([configJson], '') AS configJson,
        ISNULL([updatedByUserId], 0) AS updatedByUserId,
        [created_At],
        ISNULL(CONVERT(VARCHAR(30), updated_at, 126), '') AS updated_at
    FROM dbo.companyFeatures
    WHERE companyId = @companyId
      AND (@enabledOnly IS NULL OR @enabledOnly = 0 OR [enabled] = 1)
    FOR JSON AUTO, ROOT('companyFeatures');
END;
GO

CREATE OR ALTER PROC [dbo].[sp_companyFeatures_one] (@pjsonfile VARCHAR(MAX))
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @companyFeatureId INT;
    DECLARE @companyId INT;
    DECLARE @featureKey NVARCHAR(50);

    SELECT
        @companyFeatureId = TRY_CONVERT(INT, JSON_VALUE(value, '$.companyFeatureId')),
        @companyId = TRY_CONVERT(INT, JSON_VALUE(value, '$.companyId')),
        @featureKey = JSON_VALUE(value, '$.featureKey')
    FROM OPENJSON(@pjsonfile, '$.companyFeatures');

    SELECT
        [companyFeatureId],
        ISNULL([companyId], 0) AS companyId,
        ISNULL([featureKey], '') AS featureKey,
        ISNULL([enabled], 0) AS enabled,
        ISNULL([configJson], '') AS configJson,
        ISNULL([updatedByUserId], 0) AS updatedByUserId,
        [created_At],
        ISNULL(CONVERT(VARCHAR(30), updated_at, 126), '') AS updated_at
    FROM dbo.companyFeatures
    WHERE ([companyFeatureId] = @companyFeatureId AND @companyFeatureId IS NOT NULL)
       OR ([companyId] = @companyId AND [featureKey] = @featureKey AND @companyId IS NOT NULL AND @featureKey IS NOT NULL)
    FOR JSON AUTO, ROOT('companyFeatures');
END;
GO

